 template <typename ParseContext>
 FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
   auto it = ctx.begin();
   auto end = ctx.end();

   if (it != end && *it == 'n') {
     set_brackets({}, {});
     ++it;
   }

   if (it != end && *it != '}') {
     if (*it == 's') {
       if constexpr (detail::is_formattable_char<T, Char>::value) {
         set_brackets(detail::string_literal<Char, '"'>{},
                      detail::string_literal<Char, '"'>{});
         set_separator({});
         ++it;
       } else {
         report_error("invalid format specifier");
       }
     } else if (*it == '?') {
       if constexpr (detail::is_formattable_char<T, Char>::value) {
         ++it;
         if (it == end || *it != 's')
           report_error("invalid format specifier");
         set_brackets(detail::string_literal<Char, '"'>{},
                      detail::string_literal<Char, '"'>{});
         set_separator({});
         is_debug_format_ = true;
         ++it;
       } else {
         report_error("invalid format specifier");
       }
